/** Row bitmaps for a character (MSB = leftmost pixel); unknown characters render as "?". */
export function glyph(ch: string): number[] {
  let code = ch.charCodeAt(0);
  if (code < 32 || code > 126) code = 63;
  const off = (code - 32) * FONT_H * 2;
  const rows: number[] = [];
  for (let i = 0; i < FONT_H; i++)
    rows.push(parseInt(DATA.slice(off + i * 2, off + i * 2 + 2), 16));
  return rows;
}
